CREATE OR REPLACE FUNCTION public.user_commercial_allowed(_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active') AND (public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.user_roles s WHERE s.user_id=auth.uid() AND s.role IN ('employee','manager')) AND EXISTS(SELECT 1 FROM public.user_access_roles u JOIN public.access_roles r ON r.id=u.role_id WHERE u.user_id=auth.uid() AND _permission=ANY(r.permissions))) $$;
CREATE OR REPLACE FUNCTION public.user_commercial_company(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.companies c WHERE c.id=_company AND c.is_active AND (public.has_role(auth.uid(),'super_admin') OR public.is_company_member(auth.uid(),c.id))) $$;
CREATE OR REPLACE FUNCTION public.user_commercial_lead(_lead uuid,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.user_commercial_company(_company) AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id=_lead AND l.company_id=_company AND (public.has_role(auth.uid(),'super_admin') OR l.assigned_to=auth.uid())) $$;
CREATE TABLE public.sales_proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),created_by uuid NOT NULL DEFAULT auth.uid(),lead_id uuid REFERENCES public.leads(id),customer_id uuid REFERENCES public.sales_customers(id),deal_id uuid REFERENCES public.deals(id),number text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','accepted','rejected')),currency text NOT NULL DEFAULT 'INR' CHECK(currency ~ '^[A-Z]{3}$'),valid_until date NOT NULL,document jsonb NOT NULL DEFAULT '{}',subtotal numeric(14,2) NOT NULL DEFAULT 0,discount_total numeric(14,2) NOT NULL DEFAULT 0,tax_total numeric(14,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,number));
GRANT SELECT ON public.sales_proposals TO authenticated; GRANT ALL ON public.sales_proposals TO service_role;
ALTER TABLE public.sales_proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Scoped user proposals" ON public.sales_proposals FOR SELECT TO authenticated USING(public.user_commercial_allowed('proposal.view') AND public.user_commercial_company(company_id) AND (created_by=auth.uid() OR public.has_role(auth.uid(),'super_admin')));
CREATE TABLE public.proposal_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),proposal_id uuid NOT NULL REFERENCES public.sales_proposals(id) ON DELETE CASCADE,actor_id uuid NOT NULL DEFAULT auth.uid(),action text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.proposal_events TO authenticated; GRANT ALL ON public.proposal_events TO service_role;
ALTER TABLE public.proposal_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Scoped proposal history" ON public.proposal_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.sales_proposals p WHERE p.id=proposal_id));
ALTER TABLE public.invoices ADD COLUMN company_id uuid REFERENCES public.companies(id),ADD COLUMN lead_id uuid REFERENCES public.leads(id),ADD COLUMN deal_id uuid REFERENCES public.deals(id),ADD COLUMN proposal_id uuid REFERENCES public.sales_proposals(id),ADD COLUMN currency text NOT NULL DEFAULT 'INR';
CREATE POLICY "Owner scoped shared invoices" ON public.invoices FOR SELECT TO authenticated USING(public.user_commercial_allowed('invoice.view') AND created_by=auth.uid() AND public.user_commercial_company(company_id));
CREATE POLICY "Owner scoped invoice payments" ON public.payments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.invoices i WHERE i.id=invoice_id AND i.created_by=auth.uid() AND public.user_commercial_company(i.company_id)));
CREATE POLICY "Owner scoped invoice credits" ON public.credit_notes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.invoices i WHERE i.id=invoice_id AND i.created_by=auth.uid() AND public.user_commercial_company(i.company_id)));
CREATE POLICY "Owner scoped invoice audit" ON public.financial_audit_logs FOR SELECT TO authenticated USING(entity_type='invoice' AND EXISTS(SELECT 1 FROM public.invoices i WHERE i.id=entity_id AND i.created_by=auth.uid() AND public.user_commercial_company(i.company_id)));
CREATE POLICY "Commercial seller settings read" ON public.sales_settings FOR SELECT TO authenticated USING(public.user_commercial_allowed('invoice.view') OR public.user_commercial_allowed('proposal.view'));
CREATE POLICY "Authorized lead sales customers" ON public.sales_customers FOR SELECT TO authenticated USING((public.user_commercial_allowed('invoice.view') OR public.user_commercial_allowed('proposal.view')) AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND public.user_commercial_lead(l.id,l.company_id)));
CREATE OR REPLACE FUNCTION public.user_sales_catalog() RETURNS TABLE(id uuid,name text,selling_price numeric,tax_rate numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.name,p.selling_price,p.tax_rate FROM public.products_services p WHERE p.is_active AND (public.user_commercial_allowed('invoice.create') OR public.user_commercial_allowed('proposal.create')) $$;
CREATE OR REPLACE FUNCTION public.commercial_line_totals(_items jsonb,_mode text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE i jsonb;q numeric;p numeric;d numeric;r numeric;b numeric;t numeric;raw numeric;s numeric:=0;ds numeric:=0;ts numeric:=0;lines jsonb:='[]';BEGIN
IF _mode IS NULL OR _mode NOT IN ('none','cgst_sgst','igst') OR jsonb_typeof(_items) IS DISTINCT FROM 'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Add valid line items and tax treatment';END IF;
FOR i IN SELECT value FROM jsonb_array_elements(_items) LOOP
q:=(i->>'quantity')::numeric;p:=(i->>'unit_price')::numeric;d:=(i->>'discount_percent')::numeric;r:=(i->>'tax_rate')::numeric;
IF q IS NULL OR p IS NULL OR d IS NULL OR r IS NULL OR q::text IN ('NaN','Infinity','-Infinity') OR p::text IN ('NaN','Infinity','-Infinity') OR d::text='NaN' OR r::text='NaN' OR q<=0 OR q>1000000 OR p<0 OR p>9999999999 OR d NOT BETWEEN 0 AND 100 OR r NOT BETWEEN 0 AND 100 OR length(trim(coalesce(i->>'name','')))=0 THEN RAISE EXCEPTION 'Invalid line item';END IF;
raw:=round(q*p,2);b:=round(raw*(1-d/100),2);t:=CASE WHEN _mode='none' THEN 0 ELSE round(b*r/100,2) END;s:=s+raw;ds:=ds+raw-b;ts:=ts+t;
lines:=lines||jsonb_build_array(jsonb_build_object('product_id',i->>'product_id','name',i->>'name','quantity',q,'unit_price',p,'discount_percent',d,'tax_rate',r,'subtotal',raw,'discount',raw-b,'tax',t,'total',b+t,'cgst',CASE WHEN _mode='cgst_sgst' THEN round(t/2,2) ELSE 0 END,'sgst',CASE WHEN _mode='cgst_sgst' THEN t-round(t/2,2) ELSE 0 END,'igst',CASE WHEN _mode='igst' THEN t ELSE 0 END));
END LOOP;IF s-ds+ts<=0 THEN RAISE EXCEPTION 'Total must be positive';END IF;RETURN jsonb_build_object('items',lines,'subtotal',s,'discount',ds,'tax',ts,'total',s-ds+ts);END $$;
CREATE OR REPLACE FUNCTION public.user_proposal_action(_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.sales_proposals;pid uuid;cid uuid;lid uuid;cust uuid;did uuid;calc jsonb;doc jsonb;st text;BEGIN
IF NOT public.user_commercial_allowed('proposal.view') THEN RAISE EXCEPTION 'Proposal access required';END IF;
IF _payload->>'id' IS NOT NULL THEN SELECT * INTO p FROM public.sales_proposals WHERE id=(_payload->>'id')::uuid FOR UPDATE;IF NOT FOUND OR NOT public.user_commercial_company(p.company_id) OR (p.created_by<>auth.uid() AND NOT public.has_role(auth.uid(),'super_admin')) THEN RAISE EXCEPTION 'Proposal access denied';END IF;IF (_payload->>'version')::integer IS DISTINCT FROM p.version THEN RAISE EXCEPTION 'Proposal changed; refresh before saving';END IF;pid:=p.id;END IF;
IF _action='save' THEN
IF NOT public.user_commercial_allowed(CASE WHEN pid IS NULL THEN 'proposal.create' ELSE 'proposal.edit' END) OR (pid IS NOT NULL AND p.status<>'draft') THEN RAISE EXCEPTION 'Only authorized drafts may be edited';END IF;
cid:=(_payload->>'company_id')::uuid;lid:=nullif(_payload->>'lead_id','')::uuid;cust:=nullif(_payload->>'customer_id','')::uuid;did:=nullif(_payload->>'deal_id','')::uuid;
IF NOT public.user_commercial_company(cid) OR (pid IS NOT NULL AND cid<>p.company_id) THEN RAISE EXCEPTION 'Company access denied';END IF;
IF lid IS NOT NULL AND NOT public.user_commercial_lead(lid,cid) THEN RAISE EXCEPTION 'Lead access denied';END IF;
IF cust IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sales_customers c WHERE c.id=cust AND c.is_active AND (public.has_role(auth.uid(),'super_admin') OR public.user_commercial_lead(c.lead_id,cid))) THEN RAISE EXCEPTION 'Customer access denied';END IF;
IF lid IS NULL AND cust IS NULL THEN RAISE EXCEPTION 'Link an authorized lead or customer';END IF;
IF did IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.deals d WHERE d.id=did AND d.company_id=cid AND d.deleted_at IS NULL AND (public.has_role(auth.uid(),'super_admin') OR d.assigned_to=auth.uid()) AND (lid IS NULL OR d.lead_id=lid)) THEN RAISE EXCEPTION 'Deal access denied';END IF;
IF length(trim(coalesce(_payload->>'title','')))=0 OR coalesce(_payload->>'currency','') !~ '^[A-Z]{3}$' OR (_payload->>'valid_until')::date IS NULL THEN RAISE EXCEPTION 'Complete proposal title, currency and validity';END IF;
doc:=_payload->'document';calc:=public.commercial_line_totals(doc->'items',doc->>'tax_mode');doc:=jsonb_set(doc,'{items}',calc->'items');
IF pid IS NULL THEN INSERT INTO public.sales_proposals(company_id,lead_id,customer_id,deal_id,number,title,currency,valid_until,document,subtotal,discount_total,tax_total,total) VALUES(cid,lid,cust,did,'PROP-'||upper(substr(gen_random_uuid()::text,1,12)),trim(_payload->>'title'),_payload->>'currency',(_payload->>'valid_until')::date,doc,(calc->>'subtotal')::numeric,(calc->>'discount')::numeric,(calc->>'tax')::numeric,(calc->>'total')::numeric) RETURNING id INTO pid;
ELSE UPDATE public.sales_proposals SET lead_id=lid,customer_id=cust,deal_id=did,title=trim(_payload->>'title'),currency=_payload->>'currency',valid_until=(_payload->>'valid_until')::date,document=doc,subtotal=(calc->>'subtotal')::numeric,discount_total=(calc->>'discount')::numeric,tax_total=(calc->>'tax')::numeric,total=(calc->>'total')::numeric,version=version+1,updated_at=now() WHERE id=pid;END IF;
ELSIF _action='delete' THEN IF pid IS NULL OR p.status<>'draft' OR NOT public.user_commercial_allowed('proposal.delete') THEN RAISE EXCEPTION 'Only permitted drafts may be deleted';END IF;DELETE FROM public.sales_proposals WHERE id=pid;RETURN pid;
ELSIF _action='status' THEN st:=_payload->>'status';IF pid IS NULL OR NOT public.user_commercial_allowed('proposal.edit') OR NOT ((p.status='draft' AND st='sent') OR (p.status='sent' AND st IN ('accepted','rejected'))) OR length(trim(coalesce(_payload->>'note','')))<5 THEN RAISE EXCEPTION 'Record a valid transition and delivery/decision evidence';END IF;UPDATE public.sales_proposals SET status=st,version=version+1,updated_at=now() WHERE id=pid;
ELSIF _action='note' THEN IF pid IS NULL OR NOT public.user_commercial_allowed('proposal.edit') OR length(trim(coalesce(_payload->>'note','')))=0 THEN RAISE EXCEPTION 'Authorized note required';END IF;
ELSE RAISE EXCEPTION 'Unsupported proposal action';END IF;
INSERT INTO public.proposal_events(proposal_id,action,note) VALUES(pid,CASE WHEN _action='status' THEN 'recorded_'||st ELSE _action END,left(coalesce(_payload->>'note',''),5000));RETURN pid;END $$;
CREATE OR REPLACE FUNCTION public.user_invoice_draft(_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.invoices;pid uuid;cid uuid;lid uuid;did uuid;prop uuid;customer public.sales_customers;calc jsonb;seller jsonb;mode text;num text;BEGIN
IF NOT public.user_commercial_allowed('invoice.view') OR NOT public.user_commercial_allowed(CASE WHEN _payload->>'id' IS NULL THEN 'invoice.create' ELSE 'invoice.edit' END) THEN RAISE EXCEPTION 'Invoice draft permission required';END IF;
IF coalesce(_payload->>'status','draft')<>'draft' THEN RAISE EXCEPTION 'User actions can only save drafts';END IF;
IF _payload->>'id' IS NOT NULL THEN SELECT * INTO inv FROM public.invoices WHERE id=(_payload->>'id')::uuid FOR UPDATE;IF NOT FOUND OR inv.status<>'draft' OR (inv.created_by<>auth.uid() AND NOT public.can_manage_sales()) THEN RAISE EXCEPTION 'Only authorized existing drafts may be edited';END IF;IF inv.updated_at IS DISTINCT FROM (_payload->>'updated_at')::timestamptz THEN RAISE EXCEPTION 'Invoice changed; refresh before saving';END IF;pid:=inv.id;END IF;
cid:=(_payload->>'company_id')::uuid;lid:=nullif(_payload->>'lead_id','')::uuid;did:=nullif(_payload->>'deal_id','')::uuid;prop:=nullif(_payload->>'proposal_id','')::uuid;
IF NOT public.user_commercial_company(cid) OR (pid IS NOT NULL AND inv.company_id IS NOT NULL AND cid<>inv.company_id) THEN RAISE EXCEPTION 'Company access denied';END IF;
SELECT * INTO customer FROM public.sales_customers c WHERE c.id=(_payload->>'customer_id')::uuid AND c.is_active;IF NOT FOUND OR (NOT public.can_manage_sales() AND NOT public.user_commercial_lead(customer.lead_id,cid)) THEN RAISE EXCEPTION 'Authorized existing sales customer required';END IF;
IF lid IS NOT NULL AND (NOT public.user_commercial_lead(lid,cid) OR customer.lead_id IS DISTINCT FROM lid) THEN RAISE EXCEPTION 'Related lead does not match customer';END IF;
IF did IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.deals d WHERE d.id=did AND d.company_id=cid AND d.deleted_at IS NULL AND (public.can_manage_sales() OR d.assigned_to=auth.uid()) AND d.lead_id=customer.lead_id) THEN RAISE EXCEPTION 'Deal access denied';END IF;
IF prop IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sales_proposals p WHERE p.id=prop AND p.status='accepted' AND p.company_id=cid AND (p.created_by=auth.uid() OR public.can_manage_sales()) AND (p.customer_id=customer.id OR p.lead_id=customer.lead_id)) THEN RAISE EXCEPTION 'Accepted matching proposal required';END IF;
IF coalesce(_payload->>'currency','') !~ '^[A-Z]{3}$' OR (_payload->>'issue_date')::date IS NULL OR (_payload->>'due_date')::date IS NULL OR (_payload->>'due_date')::date<(_payload->>'issue_date')::date THEN RAISE EXCEPTION 'Valid invoice dates and currency required';END IF;
SELECT to_jsonb(s)-'id' INTO seller FROM public.sales_settings s WHERE id=true;mode:=_payload->>'tax_mode';
IF mode<>'none' AND (coalesce(seller->>'gstin','')='' OR coalesce(seller->>'state','')='' OR customer.state='') THEN RAISE EXCEPTION 'GST requires configured seller and customer tax details';END IF;
IF mode='cgst_sgst' AND lower(trim(seller->>'state'))<>lower(trim(customer.state)) OR mode='igst' AND lower(trim(seller->>'state'))=lower(trim(customer.state)) THEN RAISE EXCEPTION 'Tax treatment does not match billing states';END IF;
calc:=public.commercial_line_totals(_payload->'items',mode);num:=coalesce(seller->>'invoice_prefix','INV')||'-'||upper(substr(gen_random_uuid()::text,1,12));
IF pid IS NULL THEN INSERT INTO public.invoices(customer_id,number,kind,issue_date,due_date,status,billing_details,seller_details,tax_mode,items,subtotal,discount_total,tax_total,total,notes,payment_terms,company_id,lead_id,deal_id,proposal_id,currency) VALUES(customer.id,num,'proforma',(_payload->>'issue_date')::date,(_payload->>'due_date')::date,'draft',to_jsonb(customer)-'notes',coalesce(seller,'{}'),mode,calc->'items',(calc->>'subtotal')::numeric,(calc->>'discount')::numeric,(calc->>'tax')::numeric,(calc->>'total')::numeric,coalesce(_payload->>'notes',''),coalesce(_payload->>'payment_terms',''),cid,lid,did,prop,_payload->>'currency') RETURNING id INTO pid;
ELSE UPDATE public.invoices SET customer_id=customer.id,issue_date=(_payload->>'issue_date')::date,due_date=(_payload->>'due_date')::date,billing_details=to_jsonb(customer)-'notes',seller_details=coalesce(seller,'{}'),tax_mode=mode,items=calc->'items',subtotal=(calc->>'subtotal')::numeric,discount_total=(calc->>'discount')::numeric,tax_total=(calc->>'tax')::numeric,total=(calc->>'total')::numeric,notes=coalesce(_payload->>'notes',''),payment_terms=coalesce(_payload->>'payment_terms',''),company_id=cid,lead_id=lid,deal_id=did,proposal_id=prop,currency=_payload->>'currency',updated_at=now() WHERE id=pid;END IF;
INSERT INTO public.financial_audit_logs(entity_id,entity_type,action,detail) VALUES(pid,'invoice','user_draft_saved',jsonb_build_object('company_id',cid,'status','draft','total',calc->'total'));RETURN pid;END $$;
ALTER TABLE public.profiles ADD COLUMN display_name text NOT NULL DEFAULT '',ADD COLUMN preferences jsonb NOT NULL DEFAULT '{}';
CREATE OR REPLACE FUNCTION public.guard_user_profile_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' AND NOT public.has_role(auth.uid(),'super_admin') AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.email IS DISTINCT FROM OLD.email OR NEW.account_status IS DISTINCT FROM OLD.account_status) THEN RAISE EXCEPTION 'Account identity and status cannot be self-edited';END IF;RETURN NEW;END $$;
CREATE TRIGGER user_profile_identity BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_user_profile_identity();
REVOKE ALL ON FUNCTION public.user_commercial_allowed(text),public.user_commercial_company(uuid),public.user_commercial_lead(uuid,uuid),public.user_sales_catalog(),public.user_proposal_action(text,jsonb),public.user_invoice_draft(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.user_commercial_allowed(text),public.user_commercial_company(uuid),public.user_commercial_lead(uuid,uuid),public.user_sales_catalog(),public.user_proposal_action(text,jsonb),public.user_invoice_draft(jsonb) TO authenticated;
CREATE POLICY "Own profile image read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='user-profile-private' AND (storage.foldername(name))[1]=auth.uid()::text);